```javascript
import {
  Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial,
  EdgesGeometry, LineSegments, LineBasicNodeMaterial, BoxGeometry, Color
} from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- Dimensions ---
  const rowWidth = 3.0;
  const rowHeight = 0.5;
  const dividerHeight = 0.01;
  const borderWidth = 0.02;

  // --- Texture ---
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

  // --- Main plane ---
  const planeGeo = new PlaneGeometry(rowWidth, rowHeight);
  const planeMat = new MeshBasicNodeMaterial({
    map: texture,
    color: new Color(0x16161d) // ink as base tint
  });
  const plane = new Mesh(planeGeo, planeMat);

  // --- Divider (thin line at bottom) ---
  const dividerGeo = new PlaneGeometry(rowWidth, dividerHeight);
  const dividerMat = new MeshBasicNodeMaterial({
    color: new Color(0xe8ecf2), // paper
    transparent: true,
    opacity: 0.6
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.y = -rowHeight / 2 - dividerHeight / 2;

  // --- Focus border (edge accent) ---
  const borderGeo = new BoxGeometry(rowWidth, rowHeight, 0.02);
  const borderEdges = new EdgesGeometry(borderGeo);
  const borderMat = new LineBasicNodeMaterial({
    color: new Color(0xff2a38), // accent
    transparent: true,
    opacity: 0.0 // initially invisible
  });
  const borderLine = new LineSegments(borderEdges, borderMat);
  borderLine.position.z = 0.01; // slightly in front

  // --- Group ---
  const group = new Group();
  group.add(plane);
  group.add(divider);
  group.add(borderLine);

  // --- Position / rotation / scale from config ---
  group.position.copy(config.scenePosition || new Vector3(0, 0.7, 0));
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // --- Interactive state ---
  let hoverTL = gsap.timeline({ paused: true });
  let pressTL = gsap.timeline({ paused: true });

  // --- Handlers ---
  const handlers = {
    pointerover: () => {
      // Rise-in (subtle lift)
      hoverTL.kill();
      hoverTL = gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.5,
        ease: 'power3.out',
        overwrite: 'auto'
      });
      // Show accent border
      gsap.to(borderMat, {
        opacity: 1.0,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    pointerout: () => {
      // Return to original y
      hoverTL.kill();
      hoverTL = gsap.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.4,
        ease: 'power2.out',
        overwrite: 'auto'
      });
      // Hide accent border
      gsap.to(borderMat, {
        opacity: 0.0,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    pointerdown: () => {
      // Press-down scale
      pressTL.kill();
      pressTL = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        overwrite: 'auto'
      });
    },
    pointerup: () => {
      // Return scale
      pressTL.kill();
      pressTL = gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'back.out(2)',
        overwrite: 'auto'
      });
      // Emit select event
      if (typeof handlers.select === 'function') {
        handlers.select();
      }
    }
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    hoverTL.kill();
    pressTL.kill();
    planeGeo.dispose();
    planeMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    borderGeo.dispose();
    borderEdges.dispose();
    borderMat.dispose();
    texture.dispose();
  };

  return group;
}
